#!/usr/bin/env bash
# Generated By Claude.
# Build a RAM-only Alpine aarch64 root filesystem for the UNVR
# (Annapurna Labs Alpine V2) and wrap it as a U-Boot legacy ramdisk.
#
# Run on the Arch build box as root:   sudo ./build-rootfs.sh
#
# Needs: curl tar cpio gzip unsquashfs(squashfs-tools) mkimage(uboot-tools)
#        depmod(kmod) qemu-user-static + qemu-user-static-binfmt
set -euo pipefail

### --- settings (override via environment) ---------------------------------
VER="${VER:-latest-stable}"                  # Alpine release, e.g. v3.23
MIRROR="${MIRROR:-https://dl-cdn.alpinelinux.org/alpine}"
TFTP_DIR="${TFTP_DIR:-$HOME/tftp}"
MODLOOP="${MODLOOP:-$TFTP_DIR/modloop-lts}"  # modloop from the SAME netboot tarball as the kernel
EXTRA_PKGS="${EXTRA_PKGS:-e2fsprogs dosfstools util-linux pciutils usbutils i2c-tools nano htop}"
ROOT_PASSWORD="${ROOT_PASSWORD:-alpine}"
HOSTNAME_="${HOSTNAME_:-unvr}"
INCLUDE_FIRMWARE="${INCLUDE_FIRMWARE:-0}"    # 1 = copy /lib/firmware from modloop (large)
WORK="${WORK:-/tmp/kernel-build}"
MODULES_DIR="${MODULES_DIR:-}"               # .../lib/modules from build-kernel.sh; empty = use modloop
### --------------------------------------------------------------------------

ROOT="$WORK/rootfs"
OUT_USER="${SUDO_USER:-root}"

die() { echo "ERROR: $*" >&2; exit 1; }
[ "$(id -u)" -eq 0 ] || die "run with sudo (apk needs chroot, mknod needs root)"

for t in curl tar cpio gzip unsquashfs mkimage depmod; do
    command -v "$t" >/dev/null || die "missing tool: $t"
done
if [ -n "$MODULES_DIR" ]; then
    [ -d "$MODULES_DIR" ] || die "MODULES_DIR not found: $MODULES_DIR"
else
    [ -f "$MODLOOP" ] || die "modloop not found at $MODLOOP"
fi
[ -e /proc/sys/fs/binfmt_misc/qemu-aarch64 ] || \
    die "aarch64 binfmt not registered: pacman -S qemu-user-static qemu-user-static-binfmt && systemctl restart systemd-binfmt"

echo ">>> Clean work dir $WORK"
rm -rf "$WORK"
mkdir -p "$ROOT" "$WORK/apk"

echo ">>> Fetch apk.static ($VER)"
cd "$WORK/apk"
curl -fsSLO "$MIRROR/$VER/main/x86_64/APKINDEX.tar.gz"
tar -xzf APKINDEX.tar.gz APKINDEX
APKV=$(awk '/^P:apk-tools-static$/{f=1} f&&/^V:/{print substr($0,3); exit}' APKINDEX)
[ -n "$APKV" ] || die "could not find apk-tools-static in index"
curl -fsSLO "$MIRROR/$VER/main/x86_64/apk-tools-static-$APKV.apk"
tar -xzf "apk-tools-static-$APKV.apk" sbin/apk.static 2>/dev/null
APK="$WORK/apk/sbin/apk.static"

echo ">>> Install alpine-base + extras into rootfs"
"$APK" --arch aarch64 --root "$ROOT" --initdb --allow-untrusted --no-cache \
    -X "$MIRROR/$VER/main" -X "$MIRROR/$VER/community" \
    add alpine-base openrc busybox-openrc $EXTRA_PKGS

printf '%s\n%s\n' "$MIRROR/$VER/main" "$MIRROR/$VER/community" > "$ROOT/etc/apk/repositories"

echo ">>> Fix busybox applet symlinks (busybox --install under qemu can mis-target them)"
APPLETS=$(chroot "$ROOT" /usr/bin/env -i PATH=/usr/sbin:/usr/bin:/sbin:/bin /bin/busybox --list-full)
for p in $APPLETS; do
    # only (re)create links; never overwrite real binaries from other packages
    if [ -L "$ROOT/$p" ] || [ ! -e "$ROOT/$p" ]; then
        mkdir -p "$ROOT/$(dirname "$p")"
        ln -sfn /bin/busybox "$ROOT/$p"
    fi
done

mkdir -p "$ROOT/lib/modules"
if [ -n "$MODULES_DIR" ]; then
    echo ">>> Add kernel modules from $MODULES_DIR"
    KVER=$(ls "$MODULES_DIR" | head -n1)
    [ -n "$KVER" ] || die "no kernel version dir in $MODULES_DIR"
    cp -a "$MODULES_DIR/$KVER" "$ROOT/lib/modules/"
else
    echo ">>> Add kernel modules from modloop"
    unsquashfs -q -d "$WORK/modloop" "$MODLOOP"
    KVER=$(ls "$WORK/modloop/modules" | grep -v '^firmware$' | head -n1)
    [ -n "$KVER" ] || die "no kernel version dir in modloop"
    cp -a "$WORK/modloop/modules/$KVER" "$ROOT/lib/modules/"
fi
echo "    kernel: $KVER"
if [ "$INCLUDE_FIRMWARE" = 1 ] && [ -f "$MODLOOP" ]; then
    [ -d "$WORK/modloop" ] || unsquashfs -q -d "$WORK/modloop" "$MODLOOP"
    [ -d "$WORK/modloop/modules/firmware" ] && cp -a "$WORK/modloop/modules/firmware" "$ROOT/lib/"
fi
# Trim drivers this board has no use for, to keep the initrd small
K="$ROOT/lib/modules/$KVER/kernel"
rm -rf "$K/drivers/gpu" "$K/sound" "$K/drivers/media" "$K/drivers/net/wireless" \
       "$K/drivers/infiniband" "$K/drivers/staging" "$K/drivers/bluetooth" \
       "$K/net/bluetooth" "$K/drivers/iio" "$K/net/mac80211" "$K/net/wireless"
find "$ROOT/lib/modules/$KVER" -xtype l -delete     # drop dangling links (e.g. vmlinuz)
depmod -b "$ROOT" "$KVER"

echo ">>> Configure system (chroot via qemu)"
echo "$HOSTNAME_" > "$ROOT/etc/hostname"
INITTAB="$ROOT/etc/inittab"
sed -i 's/^tty[1-6]::/#&/' "$INITTAB"                     # no VTs on this board
if grep -q '^#*ttyS0::' "$INITTAB"; then
    sed -i 's|^#*ttyS0::.*|ttyS0::respawn:/sbin/getty -L 115200 ttyS0 vt100|' "$INITTAB"
else
    echo 'ttyS0::respawn:/sbin/getty -L 115200 ttyS0 vt100' >> "$INITTAB"
fi
grep -qx ttyS0 "$ROOT/etc/securetty" 2>/dev/null || echo ttyS0 >> "$ROOT/etc/securetty"

chroot "$ROOT" /usr/bin/env -i PATH=/usr/sbin:/usr/bin:/sbin:/bin HOME=/root /bin/sh -e <<EOF
for s in devfs dmesg mdev hwdrivers; do rc-update add \$s sysinit; done
for s in modules sysctl hostname bootmisc syslog; do rc-update add \$s boot; done
for s in mount-ro killprocs savecache; do rc-update add \$s shutdown; done
echo "root:$ROOT_PASSWORD" | chpasswd
EOF

# Early /dev nodes the kernel needs before devtmpfs is mounted, and /init
mkdir -p "$ROOT/dev"
[ -e "$ROOT/dev/console" ] || mknod -m 600 "$ROOT/dev/console" c 5 1
[ -e "$ROOT/dev/null" ]    || mknod -m 666 "$ROOT/dev/null" c 1 3
ln -sf /sbin/init "$ROOT/init"

echo ">>> Pack initramfs"
( cd "$ROOT" && find . -print0 | cpio --null --create --format=newc --quiet ) \
    | gzip -9 > "$WORK/rootfs.cpio.gz"
mkimage -A arm64 -O linux -T ramdisk -C none -n "EA-1 Alpine rootfs" \
    -d "$WORK/rootfs.cpio.gz" "$TFTP_DIR/rootfs.uImage" >/dev/null
chown "$OUT_USER": "$TFTP_DIR/rootfs.uImage"
chmod 644 "$TFTP_DIR/rootfs.uImage"

SIZE=$(stat -c %s "$TFTP_DIR/rootfs.uImage")
echo ">>> Done: $TFTP_DIR/rootfs.uImage ($((SIZE / 1024 / 1024)) MiB), kernel modules for $KVER"
# Loaded at 0x20000000 and used in place; the kernel sits at 0x30000000.
if [ "$SIZE" -gt $((0x10000000 - 0x100000)) ]; then
    echo "WARNING: ramdisk is close to/over 256 MiB and will overlap the kernel at 0x30000000." >&2
    echo "         Trim EXTRA_PKGS or move the kernel load address higher." >&2
fi
